CREATE TABLE arena_duels (id CHAR(36) PRIMARY KEY, code VARCHAR(8) NOT NULL UNIQUE, creator_user_id CHAR(36) NOT NULL, max_players TINYINT UNSIGNED NOT NULL, subjects_per_player TINYINT UNSIGNED NOT NULL, question_count TINYINT UNSIGNED NOT NULL, question_seconds SMALLINT UNSIGNED NOT NULL, status ENUM('WAITING','QUESTION_OPEN','QUESTION_RESULT','FINISHED') NOT NULL DEFAULT 'WAITING', current_position SMALLINT UNSIGNED NOT NULL DEFAULT 0, opened_at DATETIME NULL, deadline_at DATETIME NULL, created_at DATETIME NOT NULL, finished_at DATETIME NULL, CONSTRAINT fk_arena_duel_creator FOREIGN KEY (creator_user_id) REFERENCES users(id), CHECK (max_players BETWEEN 2 AND 8), CHECK (subjects_per_player BETWEEN 1 AND 5), CHECK (question_count IN (5,10,15,20)), CHECK (question_seconds IN (15,30,60))); CREATE TABLE arena_duel_players (duel_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, ready_at DATETIME NULL, joined_at DATETIME NOT NULL, score INT NOT NULL DEFAULT 0, PRIMARY KEY (duel_id,user_id), CONSTRAINT fk_arena_player_duel FOREIGN KEY (duel_id) REFERENCES arena_duels(id), CONSTRAINT fk_arena_player_user FOREIGN KEY (user_id) REFERENCES users(id)); CREATE TABLE arena_duel_subjects (duel_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, taxonomy_subject_id CHAR(36) NOT NULL, PRIMARY KEY (duel_id,user_id,taxonomy_subject_id), CONSTRAINT fk_arena_subject_player FOREIGN KEY (duel_id,user_id) REFERENCES arena_duel_players(duel_id,user_id), CONSTRAINT fk_arena_subject_taxonomy FOREIGN KEY (taxonomy_subject_id) REFERENCES taxonomy_subjects(id)); CREATE TABLE arena_duel_questions (duel_id CHAR(36) NOT NULL, position SMALLINT UNSIGNED NOT NULL, question_id CHAR(36) NOT NULL, taxonomy_subject_id CHAR(36) NULL, opened_at DATETIME NULL, closed_at DATETIME NULL, PRIMARY KEY (duel_id,position), UNIQUE KEY uq_arena_question_once (duel_id,question_id), CONSTRAINT fk_arena_question_duel FOREIGN KEY (duel_id) REFERENCES arena_duels(id), CONSTRAINT fk_arena_question_question FOREIGN KEY (question_id) REFERENCES questions(id)); CREATE TABLE arena_duel_answers (id CHAR(36) PRIMARY KEY, duel_id CHAR(36) NOT NULL, position SMALLINT UNSIGNED NOT NULL, user_id CHAR(36) NOT NULL, option_id CHAR(36) NOT NULL, received_at DATETIME(6) NOT NULL, elapsed_milliseconds INT UNSIGNED NOT NULL, is_correct BOOLEAN NULL, correct_rank TINYINT UNSIGNED NULL, points SMALLINT NOT NULL DEFAULT 0, UNIQUE KEY uq_arena_answer_once (duel_id,position,user_id), CONSTRAINT fk_arena_answer_question FOREIGN KEY (duel_id,position) REFERENCES arena_duel_questions(duel_id,position), CONSTRAINT fk_arena_answer_player FOREIGN KEY (duel_id,user_id) REFERENCES arena_duel_players(duel_id,user_id), CONSTRAINT fk_arena_answer_option FOREIGN KEY (option_id) REFERENCES question_options(id)); ALTER TABLE attempts MODIFY context ENUM('STUDY','EXAM','REVIEW','ARENA_DUELO') NOT NULL;
